window.products.push({"id":209612,"name":"Modway Revive Performance Velvet Sofa, Pink","category":"homeandappliances","retail price":0.0,"sale price":null,"image":"https://m.media-amazon.com/images/I/41C6EiXgfGS._AC_SL1000_.jpg","description":"Give new vitality to your home or apartment living space with the Revive Upholstered Performance Velvet Sofa. With a comfortable yet tailored profile and two bolster pillows, this velvet sofa beckons guests to sit and stay a while. Its durable stain-resistant performance velvet upholstery grants this sofa an approachable appeal that’s echoed by its calming color, clean lines, and splayed gold legs. Arriving directly to your doorstep in a convenient shipping box, this upholstered sofa easily unpacks to quickly become the most well-loved lounge spot in your home. Sofa Weight Capacity: 1323 lbs.","images":["https://m.media-amazon.com/images/I/41C6EiXgfGS._AC_SL1000_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"Modway","source_asin":"B08936JL75","category_path":"Home & Kitchen"},"sku":"BM-209612","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B08936JL75","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B08936JL75","price_pending":true,"merchant_ready":false});
