window.products.push({"id":209820,"name":"Donna Sharp King Comforter Set - 3 Piece Set - Canoe Trip - King Comforter and Two King Pillow Shams - Machine Washable","category":"homeandappliances","retail price":93.99,"sale price":null,"image":"https://m.media-amazon.com/images/I/81EZuW9cs-S._AC_SL1500_.jpg","description":"King comforter set includes 1 king comforter 104\"x 96\" and 2 king pillow shams 20\"x 36\". This comforter bedding set features a beautiful large plaid design with accompanied images of bears, canoes, and geometric symbols that reminds us of fun adventures in nature! This comforter bedding set has a cover that is polyester and the fill is polyester. Our rustic bedding is perfect for any cabin, lake house, mountain house, cottage, or lodge. Care Instructions: Machine wash cold separately on gentle cycle. Tumble dry. Do not bleach.","images":["https://m.media-amazon.com/images/I/81EZuW9cs-S._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"Donna Sharp","source_asin":"B0BGZ8LWCW","category_path":"Home & Kitchen"},"sku":"BM-209820","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B0BGZ8LWCW","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B0BGZ8LWCW","price_pending":true,"merchant_ready":false});
